    启示: '1. 家宅人口占，多六亲动化回头克，主全家遭灾，为极端凶兆；2. 忌神当令之月（如午火午月）为应凶高发期，需结合“冲克用神”（如午冲子）细化；3. 家宅占若见“世用自变衰败”（回头克），补救措施（如改门户）难奏效，需彻底改变环境（如迁居）',
